<?php declare(strict_types=1);
namespace Kulturhus\Verein\Web;
use Kulturhus\Native\Language\MemberCardMessages as Messages;
use Kulturhus\Native\Web\Html;

/** One member-facing card page in the existing manager, with full no-script operation. */
final class MemberCardPage
{
    public function __construct(private string $csrf,private array $messages,private string $locale='de'){}
    private function t(string $s,array $v=[]):string{return Messages::text($s,$this->messages,$v);}
    private function e(string $s,array $v=[]):string{return Html::e($this->t($s,$v));}
    private static function value(mixed $v):string{return is_scalar($v)?(string)$v:'';}
    public static function url(string $contact,array $extra=[]):string{return'?'.http_build_query(['view'=>'portal','tab'=>'card','person'=>$contact]+$extra);}
    private function start(string $action,string $contact):string{return'<form method="post" autocomplete="off">'.Html::hidden('csrf',$this->csrf).Html::hidden('action',$action).Html::hidden('contact_id',$contact);}
    private function date(string $day):string{$d=(new \DateTimeImmutable($day,new \DateTimeZone(strlen($day)>10?'UTC':'Europe/Berlin')))->setTimezone(new \DateTimeZone('Europe/Berlin'));return$d->format(($this->locale==='en'?'Y-m-d':'d.m.Y').(strlen($day)>10?' H:i:s':''));}
    public function card(array $card,string $qrUrl):string
    {
        return'<article class="member-card-face" data-member-card-face><header><strong>'.Html::e($card['club_name']).'</strong><span>'.$this->e('Mitgliederausweis').'</span></header><div class="member-card-identity"><div><h2>'.Html::e($card['name']).'</h2><dl><dt>'.$this->e('Mitgliedsnummer').'</dt><dd>'.Html::e($card['member_number']).'</dd><dt>'.$this->e('Gültig bis').'</dt><dd>'.Html::e($this->date($card['valid_until'])).'</dd></dl></div><img class="member-card-qr" src="'.Html::e($qrUrl).'" alt="'.$this->e('QR-Code zur Ausweisprüfung').'" width="168" height="168"></div><p>'.$this->e('Aktuelle Gültigkeit mit dem QR-Code prüfen.').'</p></article>';
    }
    public function recovery(string $contact,array $post,string $error):string
    {
        $revoke=($post['action']??null)==='member-card-revoke';$h='<link rel="stylesheet" href="member-cards.css"><section class="member-card-page" data-member-card-recovery><h1>'.$this->e('Mitgliederausweis').'</h1><p class="error" role="alert">'.$this->e($error).'</p><p>'.$this->e('Deine Angaben bleiben erhalten.').'</p>'.$this->start($revoke?'member-card-revoke':'member-card-issue',$contact);
        foreach($revoke?['version','request_id','card_id']:['version','request_id','source_hash']as$key)$h.=MemberCardForm::hidden($key,$post[$key]??null);
        if($revoke)$h.='<label>'.$this->e('Grund der Sperrung').'<input name="reason" value="'.Html::e(self::value($post['reason']??null)).'" maxlength="500" required></label><button class="btn btn-outline theme-secondary">'.$this->e('Erneut versuchen').'</button>';
        else{$h.='<label>'.$this->e('Gültig bis').'<input name="valid_until" value="'.Html::e(self::value($post['valid_until']??null)).'" maxlength="10" required></label>'.MemberCardForm::hidden('public_name','0').'<label class="check"><input type="checkbox" name="public_name" value="1"'.(($post['public_name']??null)==='1'?' checked':'').'>'.$this->e('Ich bestätige: Bei der QR-Prüfung dürfen Name, Verein und Gültigkeit angezeigt werden.').'</label><button class="btn btn-outline theme-secondary" name="action" value="member-card-recheck" formnovalidate>'.$this->e('Angaben erneut prüfen').'</button>';}
        return$h.'</form><a class="btn btn-outline theme-secondary" href="'.Html::e(self::url($contact)).'">'.$this->e('Aktuellen Ausweis öffnen').'</a></section>';
    }
    public function render(array $context,?array $card,array $history,array $wallet,string $error='',bool $mayConfigure=false):string
    {
        $state=$context['state'];$contact=$state['contact_id'];$issue=$context['issue'];$revoke=$context['revoke'];$current=self::url($contact);$h='<link rel="stylesheet" href="member-cards.css"><script src="member-cards.js" defer></script><section class="member-card-page" data-member-card-page><header class="member-card-heading"><h1>'.$this->e('Mitgliederausweis').'</h1><a class="btn btn-outline theme-secondary" href="'.Html::e('?'.http_build_query(!empty($state['own'])?['view'=>'portal','tab'=>'own']:['view'=>'members','id'=>$contact])).'">'.$this->e('Zum Mitgliederprofil').'</a></header>';
        if(!$card&&$state['source']){$person=$state['source']['data'];$h.='<p class="member-card-person"><strong>'.Html::e($person['name']).'</strong><br>'.Html::e($person['club_name']).'<br>'.$this->e('Mitgliedsnummer').': '.Html::e($person['member_number']).'</p>';}
        if($error!=='')$h.='<p class="error" role="alert">'.$this->e($error).'</p>';if($context['revokeStale'])$h.='<p role="alert">'.$this->e('Mitgliedschaft oder Ausweis wurde geändert. Bitte Angaben erneut prüfen.').'</p><a class="btn btn-outline theme-secondary" href="'.Html::e($current).'">'.$this->e('Aktuellen Ausweis öffnen').'</a>';if($context['saved'])$h.='<p role="status">'.$this->e('Der ursprüngliche Ausweisvorgang ist bereits gespeichert. Prüfe unten den aktuellen Ausweis.').'</p><a class="btn btn-outline theme-secondary" href="'.Html::e($current).'">'.$this->e('Aktuellen Ausweis öffnen').'</a>';
        if($card){$h.='<p class="member-card-valid" role="status">'.$this->e('Gültig').'</p>'.$this->card($card,self::url($contact,['card_asset'=>'qr','card_id'=>$card['id']])).'<div class="member-card-actions"><a class="btn btn-outline theme-secondary" target="_blank" rel="noopener" href="'.Html::e(self::url($contact,['card_asset'=>'print','card_id'=>$card['id']])).'">'.$this->e('Druckansicht öffnen').'</a>';
            foreach(['apple'=>'Zu Apple Wallet','google'=>'Zu Google Wallet']as$p=>$label)if($state['may_issue']&&!empty($wallet[$p]))$h.='<a class="btn btn-outline theme-secondary" href="'.Html::e(self::url($contact,['card_asset'=>$p,'card_id'=>$card['id']])).'" data-navigation-native'.($p==='google'?' target="_blank" rel="noopener noreferrer"':' download="mitgliederausweis.pkpass"').'>'.$this->e($label).'</a>';$h.='</div>';if($state['may_issue']&&empty($wallet['apple'])&&empty($wallet['google']))$h.='<p>'.$this->e('Wallet wird vom Verein eingerichtet.').'</p>';
        }else{$h.='<p role="status">'.$this->e(!$state['head']?'Noch kein Ausweis ausgestellt.':(!empty($state['head']['revoked'])?'Gesperrt':'Nicht gültig')).'</p>';if($state['notice'])$h.='<p>'.$this->e($state['notice']).'</p>';if(!empty($state['head']['revoked'])&&$state['head']['reason']!=='')$h.='<p>'.$this->e('Sperrgrund').': '.Html::e($state['head']['reason']).'</p>';}
        if($mayConfigure)$h.='<p><a class="btn btn-outline theme-secondary" href="?view=settings&amp;tab=member-cards">'.$this->e('Wallet einrichten').'</a></p>';
        if($state['may_issue']&&$state['source']){
            $h.='<details class="card member-card-issue"'.(!$card||$error!==''?' open':'').'><summary>'.$this->e($state['head']?'Ausweis erneuern':'Ausweis erstellen').'</summary>';if($context['issueStale'])$h.='<p role="alert">'.$this->e('Mitgliedschaft oder Ausweis wurde geändert. Bitte Angaben erneut prüfen.').'</p>';
            $h.=$this->start('member-card-issue',$contact);foreach(['version','source_hash','request_id']as$key)$h.=MemberCardForm::hidden($key,$issue[$key]);$value=self::value($issue['valid_until']);$type=preg_match('/\A[0-9]{4}-[0-9]{2}-[0-9]{2}\z/D',$value)?'date':'text';$h.='<label>'.$this->e('Gültig bis').'<input name="valid_until" type="'.$type.'" value="'.Html::e($value).'"'.($type==='date'?' min="'.Html::e($state['today']).'" max="'.Html::e($state['latest_valid_until']).'"':'').' maxlength="10" required></label>';
            $valid=in_array($issue['public_name'],['0','1'],true);$h.=MemberCardForm::hidden('public_name',$valid?'0':$issue['public_name']).'<label class="check"><input type="checkbox" name="public_name" value="1"'.($issue['public_name']==='1'?' checked':'').'>'.$this->e('Ich bestätige: Bei der QR-Prüfung dürfen Name, Verein und Gültigkeit angezeigt werden.').'</label><p>'.$this->e('Die QR-Prüfung zeigt keine Kontaktdaten, Bankdaten oder Beiträge.').'</p>';
            if($state['head'])$h.='<p>'.$this->e('Der bisherige QR-Code verliert bei der Erneuerung seine Gültigkeit.').'</p>';$h.='<button class="btn btn-solid theme-primary"'.($context['issueStale']||$context['saved']?' disabled':'').'>'.$this->e($state['head']?'Ausweis erneuern':'Ausweis erstellen').'</button>';
            if($context['issueStale']&&!$context['saved'])$h.='<button class="btn btn-outline theme-secondary" name="action" value="member-card-recheck" formnovalidate>'.$this->e('Angaben erneut prüfen').'</button>';$h.='</form></details>';
        }
        if($state['may_issue']&&$state['head']&&empty($state['head']['revoked'])){
            $h.='<details class="card member-card-revoke"'.($error!==''&&self::value($revoke['reason'])!==''?' open':'').'><summary>'.$this->e('Ausweis sperren').'</summary>'.$this->start('member-card-revoke',$contact);foreach(['version','request_id','card_id']as$key)$h.=MemberCardForm::hidden($key,$revoke[$key]);$h.='<label>'.$this->e('Grund der Sperrung').'<input name="reason" value="'.Html::e(self::value($revoke['reason'])).'" maxlength="500" required></label><button class="btn btn-outline theme-secondary"'.($context['revokeStale']||$context['saved']?' disabled':'').'>'.$this->e('Sperren').'</button></form></details>';
        }
        if($history['rows']){$h.='<details class="member-card-history"'.($history['page']>1?' open':'').'><summary>'.$this->e('Ausweisverlauf').'</summary><div class="member-card-history-grid">';foreach($history['rows']as$row)$h.='<article class="card" data-member-card-original="'.Html::e($row['id']).'"><h3>'.Html::e($row['name']).'</h3><p>'.$this->e($row['id']===($state['head']['card_id']??null)?(!empty($state['head']['revoked'])?'Gesperrt':($card?'Gültig':'Nicht gültig')):'Ersetzt').'</p><p>'.$this->e('Mitgliedsnummer').': '.Html::e($row['member_number']).'</p><p>'.$this->e('Ausgestellt am').': '.Html::e($this->date($row['issued_at'])).'<br>'.$this->e('Gültig bis').': '.Html::e($this->date($row['valid_until'])).'</p></article>';$h.='</div><p>'.$this->e('Seite {page} von {pages} · {count} Ausweise',['page'=>$history['page'],'pages'=>$history['pages'],'count'=>$history['total']]).'</p><nav>';foreach([-1=>'Vorherige Seite',1=>'Nächste Seite']as$delta=>$label){$p=$history['page']+$delta;if($p<1||$p>$history['pages'])continue;$h.='<a class="btn btn-outline theme-secondary" href="'.Html::e(self::url($contact,['card_page'=>$p])).'">'.$this->e($label).'</a>';}$h.='</nav></details>';}
        return$h.'</section>';
    }
}
